  ["off_peak_tasks", "history_deleted_at", "INTEGER"],
] as const;
const secondaryIndexesSql = "\n  CREATE INDEX IF NOT EXISTS idx_tasks_cron_automation ON tasks(cron_automation_id, updated_at DESC)\n    WHERE cron_automation_id IS NOT NULL AND deleted=0;\n  CREATE INDEX IF NOT EXISTS idx_tasks_off_peak_task ON tasks(off_peak_task_id, updated_at DESC)\n    WHERE off_peak_task_id IS NOT NULL AND deleted=0;\n  CREATE INDEX IF NOT EXISTS idx_automations_target_task ON automations(target_task_id) WHERE target_task_id IS NOT NULL;\n";
const uniqueBoundIndexSql = "CREATE UNIQUE INDEX IF NOT EXISTS idx_off_peak_bound_active ON off_peak_tasks(workspace_key,session_id) WHERE session_id IS NOT NULL AND status NOT IN ('completed','failed','cancelled')";
const duplicateBindingsSql = "SELECT 1 FROM off_peak_tasks WHERE session_id IS NOT NULL AND status NOT IN ('completed','failed','cancelled')\n    GROUP BY workspace_key, session_id HAVING count(*)>1 LIMIT 1";
const scheduledCountBackfillSql = "UPDATE automations SET scheduled_run_count=run_count";
const workflowScheduleSql = "ALTER TABLE automations ADD COLUMN studio_workflow_id TEXT";
const ledgerExistsSql = "SELECT 1 FROM sqlite_master WHERE type='table' AND name='tasks_schema_migration'";
const allIdsSql = "SELECT id FROM tasks_schema_migration";
const latestIdSql = "SELECT id FROM tasks_schema_migration ORDER BY id DESC LIMIT 1";
