    id: "0001_adopt_task_schema",
    inputs: [TASK_INDEX_SCHEMA, AUTOMATION_SCHEMA, OFF_PEAK_SCHEMA, historicalColumns,
      secondaryIndexesSql, uniqueBoundIndexSql, "scheduled-count-backfill-v1"],
    apply: adoptSchema,
  },
